// Voice notes: microphone -> a single audio blob the composer sends as an
// `audio` attachment. Nothing is streamed and nothing is transcribed here; the
// recording is one file, handed over when the visitor stops it.
import { useCallback, useEffect, useRef, useState } from 'react';

export type RecorderState = 'idle' | 'starting' | 'recording';

/** Hard stop, so a forgotten recording can't grow past what we may send. */
const MAX_SECONDS = 120;

/**
 * Chrome and Firefox record Opus in WebM; Safari records AAC in MP4 and knows
 * nothing about the first. The socket derives the stored file's extension from
 * this MIME type, so it has to be one the browser really produced.
 */
function pickMimeType(): string | undefined {
  const candidates = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4', 'audio/ogg;codecs=opus'];
  return candidates.find((type) => MediaRecorder.isTypeSupported?.(type));
}

export function isVoiceSupported(): boolean {
  return (
    typeof window !== 'undefined' &&
    typeof window.MediaRecorder !== 'undefined' &&
    Boolean(navigator.mediaDevices?.getUserMedia)
  );
}

export interface UseVoiceRecorder {
  state: RecorderState;
  seconds: number;
  start: () => void;
  /** Stops and hands the recording over. */
  stop: () => void;
  /** Stops and throws the recording away. */
  cancel: () => void;
}

export function useVoiceRecorder({
  onRecorded,
  onError,
}: {
  onRecorded: (blob: Blob) => void;
  onError: (message: string) => void;
}): UseVoiceRecorder {
  const [state, setState] = useState<RecorderState>('idle');
  const [seconds, setSeconds] = useState(0);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const keepRef = useRef(true);
  const tickRef = useRef<number | undefined>(undefined);

  const releaseMic = useCallback(() => {
    recorderRef.current?.stream.getTracks().forEach((track) => track.stop());
    recorderRef.current = null;
    window.clearInterval(tickRef.current);
    setState('idle');
    setSeconds(0);
  }, []);

  // Leaving the page or closing the panel mid-recording must not leave the
  // browser's recording indicator on.
  useEffect(() => () => releaseMic(), [releaseMic]);

  const start = useCallback(async () => {
    if (recorderRef.current || !isVoiceSupported()) return;
    setState('starting');
    let stream: MediaStream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (cause) {
      setState('idle');
      const denied = cause instanceof DOMException && (cause.name === 'NotAllowedError' || cause.name === 'SecurityError');
      onError(
        denied
          ? 'Precisamos de permissão para usar o microfone. Libere no navegador e tente novamente.'
          : 'Não conseguimos acessar o microfone.',
      );
      return;
    }

    const mimeType = pickMimeType();
    const recorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
    recorderRef.current = recorder;
    chunksRef.current = [];
    keepRef.current = true;

    recorder.ondataavailable = (event) => {
      if (event.data.size > 0) chunksRef.current.push(event.data);
    };
    recorder.onstop = () => {
      const chunks = chunksRef.current;
      chunksRef.current = [];
      const keep = keepRef.current;
      releaseMic();
      if (keep && chunks.length) onRecorded(new Blob(chunks, { type: recorder.mimeType || mimeType || 'audio/webm' }));
    };

    recorder.start();
    setState('recording');
    setSeconds(0);
    tickRef.current = window.setInterval(() => {
      setSeconds((n) => {
        const next = n + 1;
        if (next >= MAX_SECONDS) recorderRef.current?.stop();
        return next;
      });
    }, 1000);
  }, [onError, onRecorded, releaseMic]);

  const stop = useCallback(() => {
    keepRef.current = true;
    recorderRef.current?.stop();
  }, []);

  const cancel = useCallback(() => {
    keepRef.current = false;
    if (recorderRef.current) recorderRef.current.stop();
    else releaseMic();
  }, [releaseMic]);

  return { state, seconds, start: () => void start(), stop, cancel };
}

/** m:ss, the way a voice note is always labelled. */
export function clockFromSeconds(total: number): string {
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}
